description:
Implement a counter using `useReducer` instead of `useState`. The hook should return `{ count, dispatch }` where dispatch accepts `{ type: 'increment' | 'decrement' | 'reset' }` actions.

**Example:**
```tsx
const { count, dispatch } = useReducerCounter(0);
dispatch({ type: 'increment' });
```

starter_code:
import { useReducer } from 'react';

type Action = { type: 'increment' | 'decrement' | 'reset' };

export function useReducerCounter(initialValue = 0) {
  // your code here
}

test_suite:
test('starts at initial value', () => {
  const { result } = renderHook(() => useReducerCounter(5));
  expect(result.current.count).toBe(5);
});

test('increment action', () => {
  const { result } = renderHook(() => useReducerCounter());
  act(() => result.current.dispatch({ type: 'increment' }));
  expect(result.current.count).toBe(1);
});

test('decrement action', () => {
  const { result } = renderHook(() => useReducerCounter(5));
  act(() => result.current.dispatch({ type: 'decrement' }));
  expect(result.current.count).toBe(4);
});

test('reset action', () => {
  const { result } = renderHook(() => useReducerCounter(3));
  act(() => result.current.dispatch({ type: 'increment' }));
  act(() => result.current.dispatch({ type: 'reset' }));
  expect(result.current.count).toBe(3);
});

// __hidden__
test('unknown action leaves state unchanged', () => {
  const { result } = renderHook(() => useReducerCounter(10));
  act(() => result.current.dispatch({ type: 'noop' as any }));
  expect(result.current.count).toBe(10);
});

solution:
import { useReducer } from 'react';

type Action = { type: 'increment' | 'decrement' | 'reset' };

function reducer(state: number, action: Action, initial: number): number {
  switch (action.type) {
    case 'increment': return state + 1;
    case 'decrement': return state - 1;
    case 'reset': return initial;
    default: return state;
  }
}

export function useReducerCounter(initialValue = 0) {
  const [count, dispatch] = useReducer((s: number, a: Action) => reducer(s, a, initialValue), initialValue);
  return { count, dispatch };
}
